.ng-trigger-widthTransition {
    border: 2px solid #44475A;
    border-radius: 20px;
    background-color: #282A36 !important;
    transition: border-color 0.3s ease-in-out, box-shadow 0.3s ease-in-out;
    margin-left: 20px;
    margin-top: 20px;
    padding-top: 20px;
    margin-bottom: 20px;
    float: left;
    width: 100%;
    z-index: 1;
    --bard-sidenav-closed-width: 72px;
    height: auto;
}

.ng-trigger-widthTransition:hover {
    border-color: #FF79C6 !important;
    box-shadow: 0 0 12px rgba(255, 121, 198, 0.3) !important;
}

